import os
import json
from typing import Any, Dict, Optional

import requests

AZURE_CONTENT_SAFETY_ENDPOINT = os.getenv("AZURE_CONTENT_SAFETY_ENDPOINT", "").rstrip("/")
AZURE_CONTENT_SAFETY_KEY = os.getenv("AZURE_CONTENT_SAFETY_KEY", "")
AZURE_CONTENT_SAFETY_API_VERSION = os.getenv("AZURE_CONTENT_SAFETY_API_VERSION", "2023-10-01")
AZURE_CONTENT_SAFETY_MODEL = os.getenv("AZURE_CONTENT_SAFETY_MODEL", "text")

DEFAULT_CATEGORIES = {
    "Hate": 2,
    "SelfHarm": 2,
    "Sexual": 2,
    "Violence": 2,
}


class ContentSafetyError(RuntimeError):
    pass


def _normalize_thresholds(thresholds: Optional[Dict[str, int]]) -> Dict[str, int]:
    out = dict(DEFAULT_CATEGORIES)
    if thresholds:
        for k, v in thresholds.items():
            if v is None:
                continue
            out[str(k)] = int(v)
    return out


def _score_to_severity(score_value: Any) -> int:
    if isinstance(score_value, dict):
        for key in ("severity", "Severity", "score", "Score", "level", "Level"):
            if key in score_value:
                return _score_to_severity(score_value[key])
        return 0
    try:
        return int(score_value)
    except (TypeError, ValueError):
        return 0


def _extract_severities(payload: Dict[str, Any]) -> Dict[str, int]:
    severities: Dict[str, int] = {}

    for key in ("categoriesAnalysis", "categories_analysis", "categories", "CategoryAnalysis"):
        items = payload.get(key)
        if isinstance(items, list):
            for item in items:
                if not isinstance(item, dict):
                    continue
                category = item.get("category") or item.get("Category") or item.get("name") or item.get("Name")
                severity = item.get("severity") or item.get("Severity") or item.get("score") or item.get("Score")
                if category is not None:
                    severities[str(category)] = _score_to_severity(severity)
        elif isinstance(items, dict):
            for category, data in items.items():
                severities[str(category)] = _score_to_severity(data)

    if not severities:
        for cat in ("Hate", "SelfHarm", "Sexual", "Violence"):
            if cat in payload:
                severities[cat] = _score_to_severity(payload.get(cat))

    return severities


def _analyze_text_with_azure(text: str, categories: Dict[str, int]) -> Dict[str, Any]:
    if not AZURE_CONTENT_SAFETY_ENDPOINT or not AZURE_CONTENT_SAFETY_KEY:
        raise ContentSafetyError(
            "Azure Content Safety configuration missing. "
            "Set AZURE_CONTENT_SAFETY_ENDPOINT and AZURE_CONTENT_SAFETY_KEY."
        )

    url = (
        f"{AZURE_CONTENT_SAFETY_ENDPOINT}/contentsafety/text:analyze"
        f"?api-version={AZURE_CONTENT_SAFETY_API_VERSION}"
    )

    headers = {
        "Ocp-Apim-Subscription-Key": AZURE_CONTENT_SAFETY_KEY,
        "Content-Type": "application/json",
    }

    body = {
        "text": text,
        "categories": list(categories.keys()),
        "outputType": "FourSeverityLevels",
    }

    resp = requests.post(url, headers=headers, json=body, timeout=30)
    if not resp.ok:
        raise ContentSafetyError(f"Azure Content Safety request failed: {resp.status_code} {resp.text}")

    return resp.json()


def allow_text(text: str, thresholds: Optional[Dict[str, int]] = None) -> bool:
    """
    Return True if text is allowed under the provided category severity thresholds.

    Threshold semantics:
      - Each category score is compared as an integer severity level.
      - Text is blocked if any category severity is greater than or equal to its threshold.
      - Default thresholds: 2 for Hate, SelfHarm, Sexual, Violence.
    """
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    categories = _normalize_thresholds(thresholds)
    result = _analyze_text_with_azure(text, categories)
    severities = _extract_severities(result)

    for category, threshold in categories.items():
        severity = severities.get(category, 0)
        if severity >= threshold:
            return False

    return True


def evaluate_text(text: str, thresholds: Optional[Dict[str, int]] = None) -> Dict[str, Any]:
    """
    Return a structured moderation decision with category severities and allow/deny outcome.
    """
    categories = _normalize_thresholds(thresholds)
    result = _analyze_text_with_azure(text, categories)
    severities = _extract_severities(result)

    allowed = True
    blocked_categories = []
    for category, threshold in categories.items():
        severity = severities.get(category, 0)
        if severity >= threshold:
            allowed = False
            blocked_categories.append(
                {"category": category, "severity": severity, "threshold": threshold}
            )

    return {
        "allowed": allowed,
        "blocked_categories": blocked_categories,
        "categories": {k: {"severity": severities.get(k, 0), "threshold": v} for k, v in categories.items()},
        "raw": result,
    }
